mapper.select:
SELECT t.*, s.is_material_step as isMaterialStep, s.is_package_step as isPackageStep, s.is_finish_step as isFinishStep, s.step_name as stepName, s.step_code as stepCode, s.duration as duration FROM mis_production_task t LEFT JOIN mis_process_routing_step s ON t.routing_detail_id = s.id WHERE t.del_flag = '0'
AND t.task_no LIKE CONCAT('%', #{productionTaskVo.taskNo}, '%')
AND t.batch_no LIKE CONCAT('%', #{productionTaskVo.batchNo}, '%')
AND t.order_no LIKE CONCAT('%', #{productionTaskVo.orderNo}, '%')
AND t.product_code LIKE CONCAT('%', #{productionTaskVo.productCode}, '%')
AND t.product_name LIKE CONCAT('%', #{productionTaskVo.productName}, '%')
AND t.status = #{productionTaskVo.status}
AND t.task_type = #{productionTaskVo.taskType}
AND t.assigned_operator_id = #{productionTaskVo.assignedOperatorId}
AND t.company_id = #{productionTaskVo.companyId}
ORDER BY t.create_time DESC
